const items = $input.all();

return items.map((item) => {
  const data = item.json;

  const metadata = data.document_metadata || {};
  const risk = data.risk_classification || {};
  const impact = data.impact_assessment || {};
  const dra = data.deterministic_risk_assessment || {};

  const title = metadata.title || "Untitled regulatory document";
  const agency = metadata.issuing_agency || "Unknown agency";
  const documentNumber = metadata.document_number || "Unknown";
  const publicationDate = metadata.publication_date || "Unknown";
  const documentType = metadata.document_type || "Unknown";

  const regulatoryRisk =
    risk.regulatory_risk_level || dra.risk_basis?.regulatory_risk_level || "Unknown";

  const enforcementProbability =
    risk.enforcement_probability || dra.risk_basis?.enforcement_probability || "Unknown";

  const monitoringPriority =
    risk.monitoring_priority || "Unknown";

  const riskScore =
    dra.risk_score ?? "Unknown";

  const maximumScore =
    dra.maximum_score ?? "Unknown";

  const severity =
    dra.deterministic_severity || "Unknown";

  const regulatoryBurden =
    dra.risk_basis?.regulatory_burden ||
    impact.regulatory_burden ||
    "Unknown";

  const economicImpact =
    impact.economic_impact || "Unknown";

  const complianceSignificance =
    impact.compliance_significance || "Unknown";

  const urgency =
    impact.urgency || "Unknown";

  const alertMessage = [
    `🚨 REGULATORY ALERT`,
    ``,
    `Severity: ${severity}`,
    `Risk Score: ${riskScore}/${maximumScore}`,
    ``,
    `📄 ${title}`,
    ``,
    `Issuing Agency: ${agency}`,
    `Document No.: ${documentNumber}`,
    `Document Type: ${documentType}`,
    `Publication Date: ${publicationDate}`,
    ``,
    `RISK CLASSIFICATION`,
    `Regulatory Risk: ${regulatoryRisk}`,
    `Enforcement Probability: ${enforcementProbability}`,
    `Monitoring Priority: ${monitoringPriority}`,
    ``,
    `IMPACT`,
    `Regulatory Burden: ${regulatoryBurden}`,
    `Economic Impact: ${economicImpact}`,
    `Compliance Significance: ${complianceSignificance}`,
    `Urgency: ${urgency}`,
    ``,
    `Action: Review applicability and assess potential operational impact.`
  ].join("\n");

  return {
    json: {
      ...data,
      alert_message: alertMessage,
      alert_metadata: {
        title,
        agency,
        document_number: documentNumber,
        publication_date: publicationDate,
        severity,
        risk_score: riskScore,
        maximum_score: maximumScore,
        regulatory_risk_level: regulatoryRisk,
        enforcement_probability: enforcementProbability,
        monitoring_priority: monitoringPriority
      }
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const content = item.json?.choices?.[0]?.message?.content;

  if (content === undefined || content === null) {
    throw new Error("Kimi response content is missing.");
  }

  let data;

  if (typeof content === "object") {
    data = content;
  } else {
    let text = String(content).trim();

    // Remove Markdown code fences if present
    if (text.startsWith("```")) {
      text = text.replace(/^```(?:json)?\s*/i, "");
      text = text.replace(/\s*```$/i, "");
      text = text.trim();
    }

    try {
      data = JSON.parse(text);
    } catch (error) {
      throw new Error("Kimi returned invalid JSON.");
    }
  }

  // Ensure the structures expected by downstream nodes exist.
  if (!data.document_metadata) {
    data.document_metadata = {};
  }

  if (!data.risk_classification) {
    data.risk_classification = {};
  }

  if (!data.impact_assessment) {
    data.impact_assessment = {};
  }

  if (!Array.isArray(data.risk_flags)) {
    data.risk_flags = [];
  }

  // Keep Kimi's actual values.
  // Do NOT force Low/High values here.

  return {
    json: data
  };
});

const items = $input.all();

const allowedRiskLevels = ["Low", "Moderate", "High"];
const allowedEnforcement = ["Low", "Moderate", "High"];
const allowedPriority = ["Routine", "Monitor", "High"];

return items.map((item, index) => {
  const data = item.json;

  const errors = [];

  // Required top-level objects
  if (!data.document_metadata || typeof data.document_metadata !== "object") {
    errors.push("Missing document_metadata");
  }

  if (!data.risk_classification || typeof data.risk_classification !== "object") {
    errors.push("Missing risk_classification");
  }

  if (!data.impact_assessment || typeof data.impact_assessment !== "object") {
    errors.push("Missing impact_assessment");
  }

  if (!Array.isArray(data.risk_flags)) {
    errors.push("risk_flags must be an array");
  }

  // Document metadata validation
  if (data.document_metadata) {
    const requiredMetadata = [
      "title",
      "issuing_agency",
      "publication_date",
      "document_number",
      "document_type"
    ];

    for (const field of requiredMetadata) {
      if (
        typeof data.document_metadata[field] !== "string" ||
        data.document_metadata[field].trim() === ""
      ) {
        errors.push(`Missing document_metadata.${field}`);
      }
    }
  }

  // Risk classification validation
  if (data.risk_classification) {
    const risk = data.risk_classification;

    if (!allowedRiskLevels.includes(risk.regulatory_risk_level)) {
      errors.push("Invalid regulatory_risk_level");
    }

    if (!allowedEnforcement.includes(risk.enforcement_probability)) {
      errors.push("Invalid enforcement_probability");
    }

    if (!allowedPriority.includes(risk.monitoring_priority)) {
      errors.push("Invalid monitoring_priority");
    }
  }

  const valid = errors.length === 0;

  return {
    json: {
      ...data,
      validation: {
        valid,
        errors,
        checked_at: new Date().toISOString()
      }
    }
  };
});

function normalize(value) {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value).trim().toLowerCase();
}

function score(value) {
  var v = normalize(value);

  if (
    v === '' ||
    v === 'unknown' ||
    v === 'not provided' ||
    v === 'n/a' ||
    v === 'none'
  ) {
    return 0;
  }

  if (
    v.indexOf('critical') !== -1 ||
    v.indexOf('very high') !== -1 ||
    v.indexOf('severe') !== -1
  ) {
    return 4;
  }

  if (
    v.indexOf('high') !== -1 ||
    v.indexOf('significant') !== -1
  ) {
    return 3;
  }

  if (
    v.indexOf('medium') !== -1 ||
    v.indexOf('moderate') !== -1
  ) {
    return 2;
  }

  if (
    v.indexOf('low') !== -1 ||
    v.indexOf('minimal') !== -1
  ) {
    return 1;
  }

  return 0;
}

function burdenScore(value) {
  var v = normalize(value);

  if (v === '') {
    return 0;
  }

  if (
    v.indexOf('substantial increase') !== -1 ||
    v.indexOf('major increase') !== -1 ||
    v.indexOf('significantly increased') !== -1
  ) {
    return 4;
  }

  if (
    v.indexOf('increased') !== -1 ||
    v.indexOf('additional burden') !== -1 ||
    v.indexOf('new requirement') !== -1 ||
    v.indexOf('higher burden') !== -1
  ) {
    return 3;
  }

  if (
    v.indexOf('moderate') !== -1 ||
    v.indexOf('some increase') !== -1
  ) {
    return 2;
  }

  if (
    v.indexOf('reduced') !== -1 ||
    v.indexOf('decreased') !== -1 ||
    v.indexOf('streamlined') !== -1
  ) {
    return 1;
  }

  return score(v);
}

function economicScore(value) {
  var v = normalize(value);

  if (v === '') {
    return 0;
  }

  if (
    v.indexOf('major') !== -1 ||
    v.indexOf('severe') !== -1 ||
    v.indexOf('very high') !== -1
  ) {
    return 4;
  }

  if (
    v.indexOf('significant') !== -1 ||
    v.indexOf('high') !== -1
  ) {
    return 3;
  }

  if (
    v.indexOf('moderate') !== -1 ||
    v.indexOf('medium') !== -1
  ) {
    return 2;
  }

  if (
    v.indexOf('low') !== -1 ||
    v.indexOf('minimal') !== -1
  ) {
    return 1;
  }

  return 0;
}

return items.map(function(item) {

  var data = item.json || {};

  var risk = data.risk_classification || {};
  var impact = data.impact_assessment || {};

  var regulatoryRiskLevel =
    risk.regulatory_risk_level || 'Unknown';

  var enforcementProbability =
    risk.enforcement_probability || 'Unknown';

  var regulatoryBurden =
    impact.regulatory_burden || 'Unknown';

  var economicImpact =
    impact.economic_impact || 'Unknown';

  var complianceSignificance =
    impact.compliance_significance || 'Unknown';

  var urgency =
    impact.urgency || 'Unknown';

  var regulatoryRisk =
    score(regulatoryRiskLevel);

  var enforcement =
    score(enforcementProbability);

  var burden =
    burdenScore(regulatoryBurden);

  var economic =
    economicScore(economicImpact);

  var compliance =
    score(complianceSignificance);

  var urgencyScore =
    score(urgency);

  var riskScore =
    regulatoryRisk +
    enforcement +
    burden +
    economic +
    compliance +
    urgencyScore;

  var deterministicSeverity = 'Low';

  if (riskScore >= 15) {
    deterministicSeverity = 'Critical';
  } else if (riskScore >= 11) {
    deterministicSeverity = 'High';
  } else if (riskScore >= 6) {
    deterministicSeverity = 'Medium';
  }

  var alertRequired =
    deterministicSeverity === 'Critical' ||
    deterministicSeverity === 'High';

  item.json.deterministic_risk_assessment = {
    risk_score: riskScore,
    maximum_score: 24,
    deterministic_severity: deterministicSeverity,
    alert_required: alertRequired,

    risk_basis: {
      regulatory_risk_level: regulatoryRiskLevel,
      enforcement_probability: enforcementProbability,
      regulatory_burden: regulatoryBurden,
      economic_impact: economicImpact,
      compliance_significance: complianceSignificance,
      urgency: urgency
    },

    component_scores: {
      regulatory_risk: regulatoryRisk,
      enforcement_probability: enforcement,
      regulatory_burden: burden,
      economic_impact: economic,
      compliance_significance: compliance,
      urgency: urgencyScore
    }
  };

  return item;
});
